from __future__ import annotations

def singleton_matching(family: set[int], element: int) -> dict[int, int]:
    """Construct the avoiding-to-containing injection."""
    bit = 1 << element
    if bit not in family:
        raise ValueError("singleton absent")
    if any((a | b) not in family for a in family for b in family):
        raise ValueError("family is not union-closed")
    matching = {a: a | bit for a in family if not a & bit}
    assert set(matching.values()) <= family
    assert len(matching) == len(set(matching.values()))
    return matching

from __future__ import annotations

def family_from_mask(code: int, n: int) -> set[int]:
    return {a for a in range(1 << n) if code & (1 << a)}

def is_union_closed(family: set[int]) -> bool:
    return all((a | b) in family for a in family for b in family)

def has_abundant_element(family: set[int], n: int) -> bool:
    return any(2 * sum(bool(a & (1 << x)) for a in family) >= len(family)
               and any(a & (1 << x) for a in family) for x in range(n))

def verify_three_points() -> tuple[int, int]:
    eligible = counterexamples = 0
    for code in range(1 << (1 << 3)):
        family = family_from_mask(code, 3)
        if any(family) and is_union_closed(family):
            eligible += 1
            counterexamples += not has_abundant_element(family, 3)
    return eligible, counterexamples

if __name__ == "__main__":
    print(verify_three_points())

